import{T as i}from"./TheFooter-BrIcS5-T.js";import{u as r}from"./useAuth-CJh-64fS.js";import{_ as l,o as c,a as x,b as m,d as e,e as a,f as p,g as o,i as f,u,h,F as v}from"./index-DOOEPxDx.js";const b={class:"bg-primary mt-20 text-white"},g={class:"bg-secondary text-white py-20 px-6 relative"},y={class:"max-w-4xl mx-auto text-center space-y-6"},w={class:"flex justify-center mt-8"},C={class:"mt-6 md:mt-0 md:absolute md:top-1/2 md:left-4 md:transform md:-translate-y-1/2"},B={class:"mt-4 md:mt-0 md:absolute md:top-1/2 md:right-4 md:transform md:-translate-y-1/2 md:text-right"},T={__name:"Article5view",setup(_){const{isLoggedIn:n,setUserFromApi:d}=r();return c(()=>{d(),window.scrollTo(0,0)}),(k,t)=>{const s=h("router-link");return m(),x(v,null,[e("div",b,[t[5]||(t[5]=p('<section class="bg-secondary px-4 py-6 lg:py-10 text-center" data-v-5f58811d><div class="max-w-4xl mx-auto" data-v-5f58811d><h1 class="text-3xl sm:text-4xl lg:text-5xl font-extrabold leading-tight mb-2" data-v-5f58811d> How Does it Work? </h1><p class="text-white/80 text-base sm:text-lg font-medium" data-v-5f58811d>Kevin Bell, CFA</p><p class="text-white/80 text-base sm:text-lg font-medium" data-v-5f58811d>President, Cadena Bitcoin</p></div></section><section class="px-4 py-10 lg:py-14 max-w-[1000px] mx-auto space-y-6 text-base sm:text-lg leading-snug text-white/90" data-v-5f58811d><p data-v-5f58811d> Cadena Bitcoin is a decentralized lending and borrowing product where users lock Bitcoin collateral in a Discreet Log Contracts (DLC) to facilitate loans. Here’s a breakdown of the key actions: </p><div class="space-y-5" data-v-5f58811d><h2 class="text-2xl sm:text-3xl font-bold text-secondary mb-1" data-v-5f58811d>Posting an Offer</h2><p data-v-5f58811d> A user (Initiator) posts an offer on Cadena Bitcoin, locking collateral and specifying interest rate. Terms like loan size, contract tenor, loan to value, and currency (USD) are fixed at the product level. </p><h2 class="text-2xl sm:text-3xl font-bold text-secondary mb-1" data-v-5f58811d>Accepting an Offer</h2><p data-v-5f58811d> Peer accepts the offer, locking in their collateral and forming a contract. </p><h2 class="text-2xl sm:text-3xl font-bold text-secondary mb-1" data-v-5f58811d>Funding Transaction</h2><p data-v-5f58811d> The on-chain DLC holds users’ collateral, provides change, and covers Cadena Bitcoin’s service fee. </p><h2 class="text-2xl sm:text-3xl font-bold text-secondary mb-1" data-v-5f58811d>Contract Execution</h2><p data-v-5f58811d> At maturity, the Oracle’s attestation determines the contract outcome. A single Contract Execution Transaction (CET) is broadcast, splitting the locked collateral based on the BTCUSD price. </p></div><div class="space-y-5" data-v-5f58811d><h4 class="text-xl sm:text-2xl font-semibold text-secondary mb-1" data-v-5f58811d>Term</h4><p data-v-5f58811d> Each Cadena Bitcoin contract lasts 30, 90, 180, or 360 days starting when the contract is accepted. Duration may extend slightly to align with the next available Oracle attestation after maturity. </p><h4 class="text-xl sm:text-2xl font-semibold text-secondary mb-1" data-v-5f58811d>Interest</h4><p data-v-5f58811d> Simple interest using a 30/360-day count convention (commonly used in USD debt). No compounding. For tenors shorter than 1 year, the 360 day basis understates the true rate compared to a 365-day base. </p><h4 class="text-xl sm:text-2xl font-semibold text-secondary mb-1" data-v-5f58811d>Loan Size</h4><p data-v-5f58811d> Base loan value is 0.1 BTC. The borrower receives 80% of the contract sum (0.08 BTC). </p><p data-v-5f58811d><span class="font-semibold text-secondary" data-v-5f58811d>Lender contribution:</span> Base Loan / (1.0 + interest / 100)</p><p data-v-5f58811d><span class="font-semibold text-secondary" data-v-5f58811d>Borrower Loan:</span> Borrower provides 0.1 BTC plus 0.50% service fee minus lender’s contribution. </p><p data-v-5f58811d><span class="font-semibold text-secondary" data-v-5f58811d>Settlement:</span> A single Contract Execution Transaction (CET) splits collateral based on BTCUSD price at maturity. </p><p data-v-5f58811d> The lender receives 0.08 BTC × (BTC price at acceptance ÷ price at maturity). The borrower receives the remainder. </p></div></section>',2)),e("section",g,[e("div",y,[t[1]||(t[1]=e("h2",{class:"text-3xl md:text-4xl font-extrabold"}," Cadena Bitcoin Makes Bitcoin Backed Loans Simple and Transparent ",-1)),t[2]||(t[2]=e("h4",{class:"text-lg text-white/80 leading-relaxed max-w-2xl mx-auto"}," Post or accept loan offers with preset terms and Bitcoin collateral. All transactions are on chain secured by Discreet Log Contracts and settled with a single execution based on a trusted Oracle price feed. ",-1)),e("div",w,[a(s,{to:u(n)?"/btcusd":"/register",class:"inline-block rounded-full bg-white text-secondary font-semibold px-8 py-4 text-lg transition hover:bg-white/90"},{default:o(()=>[...t[0]||(t[0]=[f(" Explore Cadena Bitcoin Contracts ",-1)])]),_:1},8,["to"])])]),e("div",C,[a(s,{to:"/article/cadena-loan-lifecycle",class:"flex items-center gap-2 text-white hover:text-primary transition text-sm md:text-base font-medium max-w-[200px]"},{default:o(()=>[...t[3]||(t[3]=[e("span",{class:"text-2xl"},"←",-1),e("span",{class:"leading-tight"}," Cadena Bitcoin: Security ",-1)])]),_:1})]),e("div",B,[a(s,{to:"/article/we-need-to-talk-about-kyc",class:"flex items-center md:justify-end gap-2 text-white hover:text-primary transition text-sm md:text-base font-medium max-w-[200px]"},{default:o(()=>[...t[4]||(t[4]=[e("span",{class:"leading-tight"}," We need to talk about KYC ",-1),e("span",{class:"text-2xl"},"→",-1)])]),_:1})])])]),a(i)],64)}}},S=l(T,[["__scopeId","data-v-5f58811d"]]);export{S as default};
